/**
 * Downloads and builds the asset library into data/library:
 *   fonts/   curated Google Fonts (SIL OFL) as TTF
 *   emoji/   animated Noto Emoji (CC BY 4.0) as Lottie JSON
 *   looks/   colour-grade LUTs generated by JANUXAI
 *   sfx/     sound effects synthesised by JANUXAI
 * Run with: npm run setup:library   (safe to re-run; skips what exists)
 */
import fs from "node:fs";
import path from "node:path";
import { EMOJIS, emojiFile } from "../src/lib/library/emoji";
import { fontFile, FONTS } from "../src/lib/library/fonts";
import { libraryDir } from "../src/lib/library";
import { buildCube, LOOKS } from "../src/lib/library/looks";
import { makeSoundEffect, SFX_DEFAULT_DURATION, SFX_TYPES } from "../src/lib/studio/audioGen";

const root = libraryDir();
for (const d of ["fonts", "emoji", "looks", "sfx"]) fs.mkdirSync(path.join(root, d), { recursive: true });

async function download(url: string, dest: string) {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`${res.status} ${url}`);
  fs.writeFileSync(dest, Buffer.from(await res.arrayBuffer()));
}

async function fonts() {
  let ok = 0;
  let failed = 0;
  for (const f of FONTS) {
    const missing = f.weights.filter((w) => !fs.existsSync(path.join(root, fontFile(f.family, w))));
    if (!missing.length) {
      ok += f.weights.length;
      continue;
    }
    // Without a browser user agent, the Google Fonts CSS API serves TrueType URLs.
    const url = `https://fonts.googleapis.com/css2?family=${encodeURIComponent(f.family).replace(/%20/g, "+")}:wght@${missing.join(";")}`;
    try {
      const css = await (await fetch(url)).text();
      const blocks = [...css.matchAll(/font-weight:\s*(\d+);[\s\S]*?src:\s*url\(([^)]+\.ttf)\)/g)];
      const byWeight = new Map<number, string>();
      for (const b of blocks) if (!byWeight.has(Number(b[1]))) byWeight.set(Number(b[1]), b[2]);
      for (const w of missing) {
        const src = byWeight.get(w);
        if (!src) {
          failed++;
          continue;
        }
        await download(src, path.join(root, fontFile(f.family, w)));
        ok++;
      }
    } catch (err) {
      failed += missing.length;
      console.warn(`  font ${f.family}: ${(err as Error).message}`);
    }
  }
  console.log(`fonts: ${ok} files ready${failed ? `, ${failed} failed` : ""}`);
}

async function emoji() {
  let ok = 0;
  for (const e of EMOJIS) {
    const dest = path.join(root, emojiFile(e.code));
    if (fs.existsSync(dest)) {
      ok++;
      continue;
    }
    try {
      await download(`https://fonts.gstatic.com/s/e/notoemoji/latest/${e.code}/lottie.json`, dest);
      ok++;
    } catch (err) {
      console.warn(`  emoji ${e.name}: ${(err as Error).message}`);
    }
  }
  console.log(`emoji: ${ok}/${EMOJIS.length} animations ready`);
}

function looks() {
  for (const l of LOOKS) {
    const dest = path.join(root, "looks", `${l.id}.cube`);
    if (!fs.existsSync(dest)) fs.writeFileSync(dest, buildCube(l));
  }
  console.log(`looks: ${LOOKS.length} LUTs ready`);
}

async function sfx() {
  for (const t of SFX_TYPES) {
    const dest = path.join(root, "sfx", `${t}.wav`);
    if (!fs.existsSync(dest)) await makeSoundEffect(t, SFX_DEFAULT_DURATION[t], dest);
  }
  console.log(`sfx: ${SFX_TYPES.length} sound effects ready`);
}

(async () => {
  console.log(`Setting up the asset library in ${root}`);
  await fonts();
  await emoji();
  looks();
  await sfx();
  fs.writeFileSync(path.join(root, "installed.json"), JSON.stringify({ at: new Date().toISOString() }));
  console.log("Asset library ready.");
})().catch((err) => {
  console.error(err);
  process.exit(1);
});
